const key = 'quittances-v1';
const euro = n => +n ? new Intl.NumberFormat('fr-FR', {style:'currency', currency:'EUR'}).format(n) : '';
const euroOrBlank = n => +n ? euro(n) : '';
const amountValue = value => +String(value ?? '').replace(/[^\d,.-]/g,'').replace(',','.') || 0;
const monthLabel = m => new Intl.DateTimeFormat('fr-FR', {month:'long', year:'numeric'}).format(new Date(`${m}-01T12:00:00`));
const isoToday = () => new Date().toISOString().slice(0,10);
const attributeValue = value => String(value ?? '').replace(/&/g,'&amp;').replace(/"/g,'&quot;').replace(/</g,'&lt;');
const htmlValue = value => String(value ?? '').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
let state = JSON.parse(localStorage.getItem(key) || 'null') || {settings:{name:'',year:new Date().getFullYear(),start:'',rent:0,charges:0,coefficient:100},months:[],payments:[]};
let paymentDrafts = {};
function save(){ localStorage.setItem(key, JSON.stringify(state)); }
function backupFileName(){ return `quittances-sauvegarde-${new Date().toISOString().replace(/[-:]/g,'').replace(/\..+/, '')}.json`; }
function storeSettingsForm(){ const next=Object.fromEntries(new FormData(document.querySelector('#settings'))); state.settings={...next,rent:amountValue(next.rent),charges:amountValue(next.charges),coefficient:+next.coefficient||100}; }
function downloadBackup(){
  storeSettingsForm(); save();
  const content=JSON.stringify({format:'quittances-backup',version:1,savedAt:new Date().toISOString(),data:state},null,2);
  const link=document.createElement('a'); link.href=URL.createObjectURL(new Blob([content],{type:'application/json'})); link.download=backupFileName(); link.click(); URL.revokeObjectURL(link.href);
}
function dates(){
  const {year,start}=state.settings; if(!year) return [];
  const now=new Date(), limit=`${Math.min(+year,now.getFullYear())}-${String(now.getMonth()+1).padStart(2,'0')}`;
  let cursor=start ? start.slice(0,7) : `${year}-01`; if(cursor.slice(0,4)!==String(year)) cursor=`${year}-01`;
  const result=[]; while(cursor<=limit){ result.push(cursor); const [y,m]=cursor.split('-').map(Number); cursor=`${m===12?y+1:y}-${String(m===12?1:m+1).padStart(2,'0')}`; } return result;
}
function scheduled(month){
  const changed=state.months.find(x=>x.month===month), base=state.settings;
  const value=changed || {rent:base.rent,charges:base.charges,coefficient:base.coefficient};
  return {...value, month, rent:+value.rent||0, charges:+value.charges||0, coefficient:+value.coefficient||0, total:((+value.rent||0)+(+value.charges||0))*(+value.coefficient||0)/100};
}
function paymentsFor(month){ return state.payments.filter(p=>p.month===month); }
function paid(month, source){ return paymentsFor(month).filter(p=>!source || p.source===source).reduce((sum,p)=>sum+(+p.amount||0),0); }
function cumulative(values){ let total=0; return values.map(value=>(total+=value,total)); }
function setMonthCoefficient(month, coefficient){ const base=scheduled(month); state.months=state.months.filter(x=>x.month!==month); state.months.push({month,rent:base.rent,charges:base.charges,coefficient:+coefficient||0}); save(); render(); }
function paymentOptions(selected){ return dates().map(month=>`<option value="${month}"${month===selected?' selected':''}>${monthLabel(month)}</option>`).join(''); }
function rowAmount(row, field){ const element=row.querySelector(`[data-field="${field}"]`), value=element.value ?? element.textContent; return +String(value).replace(/[\s€]/g,'').replace(',','.')||0; }
function rememberPaymentDraft(row){ paymentDrafts[row.dataset.id]={date:row.querySelector('[data-field="date"]').value,month:row.querySelector('[data-field="month"]').value,note:row.querySelector('[data-field="note"]').value,locataire:rowAmount(row,'locataireAmount'),caf:rowAmount(row,'cafAmount'),charges:rowAmount(row,'chargeAmount')}; }
function restorePaymentDrafts(){ for(const [id,draft] of Object.entries(paymentDrafts)){ const row=document.querySelector(`#payments tr[data-id="${id}"]`); if(!row) continue; row.querySelector('[data-field="date"]').value=draft.date; row.querySelector('[data-field="month"]').value=draft.month; row.querySelector('[data-field="note"]').value=draft.note; row.querySelector('[data-field="locataireAmount"]').textContent=euro(draft.locataire); row.querySelector('[data-field="cafAmount"]').textContent=euro(draft.caf); row.querySelector('[data-field="chargeAmount"]').textContent=euro(draft.charges); row.querySelector('.payment-rent').textContent=euro(draft.locataire+draft.caf-draft.charges); row.querySelector('.payment-total').textContent=euro(draft.locataire+draft.caf); const button=row.querySelector('.delete-payment'); button.textContent='Valider'; button.classList.add('validate-payment'); } }
function exportPdf(){
  const ds=dates(), dueCumulative=cumulative(ds.map(month=>scheduled(month).total)), paidCumulative=cumulative(ds.map(month=>paid(month)));
  const paymentTotals=state.payments.reduce((totals,p)=>({locataire:totals.locataire+(p.source==='Locataire'?(+p.amount||0):0),caf:totals.caf+(p.source==='CAF'?(+p.amount||0):0),charges:totals.charges+(+p.chargeAmount||0),loyer:totals.loyer+Math.max(0,(+p.amount||0)-(+p.chargeAmount||0)),total:totals.total+(+p.amount||0)}),{locataire:0,caf:0,charges:0,loyer:0,total:0});
  const dueTotal=dueCumulative.at(-1)||0, paidTotal=paidCumulative.at(-1)||0, totalLocataire=state.payments.filter(p=>p.source==='Locataire').reduce((sum,p)=>sum+(+p.amount||0),0), totalCaf=state.payments.filter(p=>p.source==='CAF').reduce((sum,p)=>sum+(+p.amount||0),0), totalDivers=state.payments.filter(p=>p.source==='Divers').reduce((sum,p)=>sum+(+p.amount||0),0);
  const formatDate=value=>value?new Intl.DateTimeFormat('fr-FR').format(new Date(`${value}T12:00:00`)):'';
  const paymentRows=state.payments.slice().sort((a,b)=>b.date.localeCompare(a.date)).map(p=>`<tr><td>${formatDate(p.date)}</td><td class="month">${monthLabel(p.month)}</td><td class="num">${p.source==='Locataire'?euro(p.amount):''}</td><td class="num">${p.source==='CAF'?euro(p.amount):''}</td><td>${htmlValue(p.note)}</td><td class="num">${euro(p.chargeAmount)}</td><td class="num">${euro((+p.amount||0)-(+p.chargeAmount||0))}</td><td class="num">${euro(p.amount)}</td></tr>`).join('') || '<tr><td colspan="8" class="empty">Aucun paiement enregistré.</td></tr>';
  const recapRows=ds.map((month,index)=>`<tr><td class="month">${monthLabel(month)}</td><td class="num">${euroOrBlank(paid(month,'Locataire'))}</td><td class="num">${euroOrBlank(paid(month,'CAF'))}</td><td class="num">${euroOrBlank(paid(month,'Divers'))}</td><td class="num">${euroOrBlank(dueCumulative[index])}</td><td class="num">${euroOrBlank(paidCumulative[index])}</td><td class="num balance">${euroOrBlank(dueCumulative[index]-paidCumulative[index])}</td></tr>`).join('') || '<tr><td colspan="7" class="empty">Aucune situation disponible.</td></tr>';
  const printWindow=window.open('', '_blank'); if(!printWindow) return alert('Autorisez les fenêtres contextuelles pour créer le PDF.');
  printWindow.document.write(`<!doctype html><html lang="fr"><head><meta charset="utf-8"><title>GESTION DU LOYER - ${state.settings.year||''}</title><style>@page{size:A4 landscape;margin:10mm}*{box-sizing:border-box}body{margin:0;color:#153234;font:9pt/1.25 Arial,sans-serif}h1{margin:0 0 2mm;font:700 16pt Georgia,serif}h2{margin:5mm 0 2mm;font:700 13pt Georgia,serif}.date{margin:0;color:#647678;font-size:8pt}.section{break-inside:avoid}table{width:100%;border-collapse:collapse;table-layout:fixed}th{padding:2mm 1.5mm;text-align:left;border-bottom:1pt solid #dfe4dc;color:#d76847;font-size:7pt;letter-spacing:.05em;text-transform:uppercase}td{padding:1.5mm;border-bottom:1pt solid #cdd7d1;vertical-align:top}.num{text-align:right;font-variant-numeric:tabular-nums;white-space:nowrap}.month{white-space:nowrap}.totals th{color:#153234;font-size:8pt;text-transform:none}.balance{color:#d76847}.empty{text-align:center;color:#647678}@media print{body{-webkit-print-color-adjust:exact;print-color-adjust:exact}}</style></head><body><h1>GESTION DU LOYER${state.settings.name ? ` ${htmlValue(state.settings.name)}` : ''}</h1><p class="date">Export du ${new Intl.DateTimeFormat('fr-FR',{dateStyle:'long'}).format(new Date())}</p><section class="section"><h2>Payements effectués</h2><table><thead><tr class="totals"><th colspan="2">Totaux</th><th class="num">${euro(paymentTotals.locataire)}</th><th class="num">${euro(paymentTotals.caf)}</th><th></th><th class="num">${euro(paymentTotals.charges)}</th><th class="num">${euro(paymentTotals.loyer)}</th><th class="num">${euro(paymentTotals.total)}</th></tr><tr><th>Date</th><th>Mois affecté</th><th>Locataire</th><th>CAF</th><th>Commentaire</th><th>Charges</th><th>Loyer</th><th>Total</th></tr></thead><tbody>${paymentRows}</tbody></table></section><section class="section"><h2>Situation par mois</h2><table><thead><tr class="totals"><th>Totaux</th><th class="num">${euro(totalLocataire)}</th><th class="num">${euro(totalCaf)}</th><th class="num">${euro(totalDivers)}</th><th class="num">${euro(dueTotal)}</th><th class="num">${euro(paidTotal)}</th><th class="num balance">${euro(dueTotal-paidTotal)}</th></tr><tr><th>Mois</th><th>Versé locataire</th><th>Versé CAF</th><th>Divers</th><th>Cumul dû</th><th>Cumul versé</th><th>Reste dû</th></tr></thead><tbody>${recapRows}</tbody></table></section></body></html>`);
  printWindow.document.close(); setTimeout(()=>{ printWindow.focus(); printWindow.print(); },100);
}
function renderRecap(ds,dueCumulative,paidCumulative,dueTotal,paidTotal){
  const totalLocataire=state.payments.filter(p=>p.source==='Locataire').reduce((sum,p)=>sum+(+p.amount||0),0), totalCaf=state.payments.filter(p=>p.source==='CAF').reduce((sum,p)=>sum+(+p.amount||0),0), totalDivers=state.payments.filter(p=>p.source==='Divers').reduce((sum,p)=>sum+(+p.amount||0),0), balance=dueTotal-paidTotal;
  document.querySelector('#recapTotals').innerHTML=`<th>Totaux</th><th class="money">${euroOrBlank(totalLocataire)}</th><th class="money">${euroOrBlank(totalCaf)}</th><th class="money">${euroOrBlank(totalDivers)}</th><th class="money">${euroOrBlank(dueTotal)}</th><th class="money">${euroOrBlank(paidTotal)}</th><th class="balance ${balance>0?'negative':''}">${euroOrBlank(balance)}</th>`;
  document.querySelector('#recap').innerHTML=ds.map((month,index)=>`<tr><td>${monthLabel(month)}</td><td class="money">${euroOrBlank(paid(month,'Locataire'))}</td><td class="money">${euroOrBlank(paid(month,'CAF'))}</td><td class="money">${euroOrBlank(paid(month,'Divers'))}</td><td class="money">${euroOrBlank(dueCumulative[index])}</td><td class="money">${euroOrBlank(paidCumulative[index])}</td><td class="balance ${dueCumulative[index]-paidCumulative[index]>0?'negative':''}">${euroOrBlank(dueCumulative[index]-paidCumulative[index])}</td></tr>`).join('') || '<tr><td colspan="7">L’échéancier apparaîtra ici.</td></tr>';
}
function render(){
  document.querySelector('#today').textContent=new Intl.DateTimeFormat('fr-FR',{dateStyle:'long'}).format(new Date());
  for(const [name,value] of Object.entries(state.settings)){ const input=document.querySelector(`[name="${name}"]`); if(input) input.value=name==='rent'||name==='charges'?euro(value):value ?? ''; }
  document.querySelector('#tenantName').value=state.settings.name ?? '';
  document.querySelector('#tenantNameTitle').textContent=state.settings.name ? ` ${state.settings.name}` : '';
  const ds=dates(), dueByMonth=ds.map(m=>scheduled(m).total), paidByMonth=ds.map(m=>paid(m));
  const dueCumulative=cumulative(dueByMonth), paidCumulative=cumulative(paidByMonth);
  const dueTotal=dueCumulative.at(-1)||0, paidTotal=paidCumulative.at(-1)||0;
  let receipt='—'; for(let i=0;i<ds.length;i++){ if(paidTotal>=dueCumulative[i]) receipt=ds[i]; else break; }
  document.querySelector('#summary').innerHTML=[['Total dû à ce jour',euro(dueTotal)],['Total versé',euro(paidTotal)],['Reste dû',euro(Math.max(0,dueTotal-paidTotal))],['Mois de quittance',receipt==='—'?'Aucun':monthLabel(receipt)]].map((item,index)=>`<article class="card ${index===2&&dueTotal-paidTotal>0?'alert':''}"><span>${item[0]}</span><strong>${item[1]}</strong></article>`).join('');
  document.querySelector('#months').innerHTML=ds.map((month,index)=>{const x=scheduled(month);return `<tr><td>${monthLabel(month)}</td><td class="money">${euro(x.rent)}</td><td class="money">${euro(x.charges)}</td><td><input class="coefficient-input" type="number" min="0" max="100" step="0.01" value="${x.coefficient}" data-month="${month}" aria-label="Coefficient d’occupation pour ${monthLabel(month)}"> <span class="unit">%</span></td><td class="money">${euro(x.total)}</td><td class="money">${euro(dueCumulative[index])}</td></tr>`}).join('') || '<tr><td colspan="6">Renseignez la date d’entrée pour créer l’échéancier.</td></tr>';
  document.querySelector('#paymentMonth').innerHTML=ds.map(m=>`<option value="${m}">${monthLabel(m)}</option>`).join('');
  const paymentTotals=state.payments.reduce((totals,p)=>({locataire:totals.locataire+(p.source==='Locataire'?(+p.amount||0):0),caf:totals.caf+(p.source==='CAF'?(+p.amount||0):0),charges:totals.charges+(+p.chargeAmount||0),loyer:totals.loyer+Math.max(0,(+p.amount||0)-(+p.chargeAmount||0)),total:totals.total+(+p.amount||0)}),{locataire:0,caf:0,charges:0,loyer:0,total:0});
  document.querySelector('#paymentTotals').innerHTML=`<th colspan="2">Totaux</th><th class="money">${euro(paymentTotals.locataire)}</th><th class="money">${euro(paymentTotals.caf)}</th><th></th><th class="money">${euro(paymentTotals.charges)}</th><th class="money">${euro(paymentTotals.loyer)}</th><th class="money">${euro(paymentTotals.total)}</th><th></th>`;
  document.querySelector('#payments').innerHTML=state.payments.slice().sort((a,b)=>b.date.localeCompare(a.date)).map(p=>`<tr data-id="${p.id}"><td><input class="payment-edit" data-field="date" type="date" value="${p.date}" aria-label="Date du paiement"></td><td><select class="payment-edit" data-field="month" aria-label="Mois affecté">${paymentOptions(p.month)}</select></td><td class="money payment-edit editable-amount" data-field="locataireAmount" contenteditable="true" aria-label="Versement locataire">${p.source==='Locataire'?euro(p.amount):''}</td><td class="money payment-edit editable-amount" data-field="cafAmount" contenteditable="true" aria-label="Versement CAF">${p.source==='CAF'?euro(p.amount):''}</td><td><input class="payment-edit" data-field="note" value="${attributeValue(p.note)}" aria-label="Commentaire"></td><td class="money payment-edit editable-amount" data-field="chargeAmount" contenteditable="true" aria-label="Part charges">${euro(p.chargeAmount)}</td><td class="money payment-rent">${euro((+p.amount||0)-(+p.chargeAmount||0))}</td><td class="money payment-total">${euro(p.amount)}</td><td><button class="small-delete delete-payment" data-id="${p.id}">Supprimer</button></td></tr>`).join('') || '<tr><td colspan="9">Aucun paiement enregistré.</td></tr>';
  document.querySelector('#recap').innerHTML=ds.map((month,index)=>`<tr><td>${monthLabel(month)}</td><td class="money">${euro(dueCumulative[index])}</td><td class="money">${euro(paid(month,'Locataire'))}</td><td class="money">${euro(paid(month,'CAF'))}</td><td class="money">${euro(paid(month,'Divers'))}</td><td class="money">${euro(paidCumulative[index])}</td><td class="balance ${dueCumulative[index]-paidCumulative[index]>0?'negative':''}">${euro(dueCumulative[index]-paidCumulative[index])}</td></tr>`).join('') || '<tr><td colspan="7">L’échéancier apparaîtra ici.</td></tr>';
  renderRecap(ds,dueCumulative,paidCumulative,dueTotal,paidTotal);
  restorePaymentDrafts();
}
document.querySelector('#saveSettings').onclick=()=>{ storeSettingsForm(); save(); render(); };
document.querySelector('#months').onchange=event=>{ const input=event.target.closest('.coefficient-input'); if(input) setMonthCoefficient(input.dataset.month,input.value); };
document.querySelector('#paymentForm').onsubmit=event=>{ event.preventDefault(); const values=Object.fromEntries(new FormData(event.target)), locataire=+values.locataireAmount||0, caf=+values.cafAmount||0, total=locataire+caf, charges=+values.chargeAmount||0; if(!total) return alert('Saisissez un montant pour le locataire ou la CAF.'); if(charges>total) return alert('La part de charges ne peut pas dépasser le règlement.'); let chargesRestantes=charges; for(const [source,amount] of [['Locataire',locataire],['CAF',caf]]){ if(!amount) continue; const chargeAmount=Math.min(amount,chargesRestantes); chargesRestantes-=chargeAmount; state.payments.push({id:crypto.randomUUID(),date:values.date,month:values.month,source,note:values.note,amount,chargeAmount}); } save(); event.target.reset(); event.target.date.value=isoToday(); render(); };
document.querySelector('#payments').oninput=event=>{ const input=event.target.closest('.payment-edit'); if(!input) return; const row=input.closest('tr'), button=row.querySelector('.delete-payment'), locataire=rowAmount(row,'locataireAmount'), caf=rowAmount(row,'cafAmount'), charges=rowAmount(row,'chargeAmount'), total=locataire+caf; rememberPaymentDraft(row); button.textContent='Valider'; button.classList.add('validate-payment'); row.querySelector('.payment-rent').textContent=euro(total-charges); row.querySelector('.payment-total').textContent=euro(total); };
document.querySelector('#payments').onchange=event=>{ const input=event.target.closest('.payment-edit'); if(!input) return; const row=input.closest('tr'), button=row.querySelector('.delete-payment'); rememberPaymentDraft(row); button.textContent='Valider'; button.classList.add('validate-payment'); };
document.querySelector('#payments').onclick=event=>{ const button=event.target.closest('.delete-payment'); if(!button) return; if(!button.classList.contains('validate-payment')){ delete paymentDrafts[button.dataset.id]; state.payments=state.payments.filter(p=>p.id!==button.dataset.id); save(); render(); return; } const row=button.closest('tr'), index=state.payments.findIndex(p=>p.id===button.dataset.id), locataire=rowAmount(row,'locataireAmount'), caf=rowAmount(row,'cafAmount'), charges=rowAmount(row,'chargeAmount'), total=locataire+caf; if(index<0) return; if(!total) return alert('Saisissez un montant pour le locataire ou la CAF.'); if(charges>total) return alert('La part de charges ne peut pas dépasser le règlement.'); let chargesRestantes=charges; const updated=[]; for(const [source,amount] of [['Locataire',locataire],['CAF',caf]]){ if(!amount) continue; const chargeAmount=Math.min(amount,chargesRestantes); chargesRestantes-=chargeAmount; updated.push({id:updated.length?crypto.randomUUID():button.dataset.id,date:row.querySelector('[data-field="date"]').value,month:row.querySelector('[data-field="month"]').value,source,note:row.querySelector('[data-field="note"]').value.trim(),amount,chargeAmount}); } delete paymentDrafts[button.dataset.id]; state.payments.splice(index,1,...updated); save(); render(); };
document.querySelector('#reset').onclick=()=>{ if(confirm('Attention : cette action effacera toutes les données locales de QUITTANCES sur cet ordinateur. Les fichiers de sauvegarde déjà téléchargés ne seront pas supprimés. Continuer ?')){ localStorage.removeItem(key); location.reload(); } };
document.querySelector('#saveFile').onclick=downloadBackup;
document.querySelector('#refreshApp').onclick=()=>window.location.reload();
document.querySelector('#quitApp').onclick=()=>{ window.close(); setTimeout(()=>alert('Le navigateur empêche la fermeture automatique. Fermez cet onglet ou cette fenêtre pour quitter l’application.'),150); };
document.querySelector('#exportSituation').onclick=exportPdf;
document.querySelector('#restoreFile').onclick=()=>document.querySelector('#restoreInput').click();
document.querySelector('#restoreInput').onchange=async event=>{ const file=event.target.files?.[0]; event.target.value=''; if(!file) return; try{ const backup=JSON.parse(await file.text()); if(backup?.format!=='quittances-backup'||!backup.data?.settings||!Array.isArray(backup.data.months)||!Array.isArray(backup.data.payments)) throw new Error('invalid'); if(!confirm('Restaurer cette sauvegarde ? Le travail actuellement affiché sera remplacé.')) return; state=backup.data; save(); render(); document.querySelector('#paymentForm').date.value=isoToday(); }catch{ alert('Ce fichier n’est pas une sauvegarde QUITTANCES valide.'); } };
document.querySelector('#paymentForm').date.value=isoToday(); render();
